def task PlaceMedicineOnTable(;){
    state nav_ok: bool;
    state nav_msg: string;
    state pick_ok: bool;
    state pick_msg: string;
    state place_ok: bool;
    state place_msg: string;

    sequence{
        do NavTo(robot_name="CAR", x=1.85, y=1.5, tolerance=0.5; success->nav_ok, message->nav_msg);
        check(nav_ok == true);
        do Pick(robot_name="CAR", object_name="FRONT_CRATE"; success->pick_ok, message->pick_msg);
        check(pick_ok == true);
        do NavTo(robot_name="CAR", x=-2.0, y=-1.8, tolerance=0.5; success->nav_ok, message->nav_msg);
        check(nav_ok == true);
        do Place(robot_name="CAR", object_name="FRONT_CRATE", location_name="TEMP_ZONE"; success->place_ok, message->place_msg);
        check(place_ok == true);
        do NavTo(robot_name="CAR", x=2.55, y=1.5, tolerance=0.5; success->nav_ok, message->nav_msg);
        check(nav_ok == true);
        do Pick(robot_name="CAR", object_name="MEDICINE_BOTTLE"; success->pick_ok, message->pick_msg);
        check(pick_ok == true);
        do NavTo(robot_name="CAR", x=-2.3, y=2.0, tolerance=0.5; success->nav_ok, message->nav_msg);
        check(nav_ok == true);
        do Place(robot_name="CAR", object_name="MEDICINE_BOTTLE", location_name="MEDICAL_TABLE"; success->place_ok, message->place_msg);
        check(place_ok == true);
    }
}
